public class Main {
    static int n, count_total, result;
    static List<Integer>[] data = new ArrayList[15];
    static long[] partial_sum = new long[15];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        for (int i = 0; i < 15; i++) {
            data[i] = new ArrayList<>();
        }
        build(0, 0);
        for (int i = 0; i <= 7; i++) {
            Collections.sort(data[i]);
        }
        count_total = 0;
        result = 0;
        for (int i = 1; i <= 9; i++) {
            compute(i);
        }
        System.out.println(result);
    }

    static void build(int level, int num) {
        if (level == 7) return;
        count_total++;
        int modVal = ((count_total - num) % 998244353 + 998244353) % 998244353;
        data[level].add(modVal);
        partial_sum[level] = (partial_sum[level] + modVal) % 1000000007;
        for (int digit = 0; digit <= 9; digit++) {
            build(level + 1, num * 10 + digit);
        }
    }

    static void compute(int x) {
        if (x > n) return;
        if (x * 1000000 + 999999 <= n && x * 10000000 > n) {
            int current_count = count_total;
            for (int i = 0, factor = 1; i <= 6; i++, factor *= 10) {
                int size = data[i].size();
                int diff = (int)(((long)(current_count - x * factor) % 998244353 + 998244353) % 998244353);
                int target = 1000000000 - diff;
                int pos = lowerBound(data[i], target);
                result = (int)((result + (long)diff * size + partial_sum[i]) % 1000000007);
                int subtractVal = (int)((998244353L * (size - pos)) % 1000000007);
                result = (result - subtractVal + 1000000007) % 1000000007;
                current_count += size;
            }
            return;
        }
        count_total++;
        int val = (int)(((long)(count_total - x) % 998244353 + 998244353) % 998244353);
        result = (result + val) % 1000000007;
        for (int digit = 0; digit <= 9; digit++) {
            compute(x * 10 + digit);
        }
    }

    static int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
